{"command":"cd /workspace/src && cat > logger.rs <<'EOF'
//! Minimal terminal logger.
//!
//! Output format: `HH:MM:SS [LEVEL] message`, with the thread number and
//! module target for debug/trace messages.  Errors go to stderr, everything
//! else goes to stdout.

use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

static MAX_LEVEL: AtomicUsize = AtomicUsize::new(2);
static COLOUR: AtomicBool = AtomicBool::new(false);

pub fn init(verbosity: u8) {
    let lvl = match verbosity {
        0 => Level::Warn,
        1 => Level::Info,
        2 => Level::Debug,
        _ => Level::Trace,
    };
    MAX_LEVEL.store(lvl as usize, Ordering::SeqCst);
    COLOUR.store(env_allows_colour(), Ordering::SeqCst);
}

fn env_allows_colour() -> bool {
    match std::env::var_os("TERM") {
        None => return false,
        Some(t) => {
            if t == "dumb" {
                return false;
            }
        }
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    true
}

#[inline]
pub fn enabled(level: Level) -> bool {
    (level as usize) <= MAX_LEVEL.load(Ordering::Relaxed)
}

pub fn thread_num() -> String {
    let id = format!("{:?}", std::thread::current().id());
    id.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .to_string()
}

fn timestamp() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let day = secs % 86400;
    format!("{:02}:{:02}:{:02}", day / 3600, (day % 3600) / 60, day % 60)
}

pub fn log(level: Level, target: &str, args: std::fmt::Arguments) {
    if !enabled(level) {
        return;
    }
    let (name, colour) = match level {
        Level::Error => ("ERROR", 31),
        Level::Warn => ("WARN", 33),
        Level::Info => ("INFO", 34),
        Level::Debug => ("DEBUG", 36),
        Level::Trace => ("TRACE", 37),
    };
    let mut line = String::with_capacity(128);
    line.push_str(&timestamp());
    line.push(' ');
    if COLOUR.load(Ordering::Relaxed) {
        line.push_str(&format!("\x1b[0m\x1b[{}m[{}] \x1b[0m", colour, name));
    } else {
        line.push('[');
        line.push_str(name);
        line.push_str("] ");
    }
    if level >= Level::Debug {
        line.push('(');
        line.push_str(&thread_num());
        line.push_str(") ");
        line.push_str(target);
        line.push_str(": ");
    }
    line.push_str(&format!("{}", args));
    line.push('\n');

    if level == Level::Error {
        let stderr = std::io::stderr();
        let mut h = stderr.lock();
        let _ = h.write_all(line.as_bytes());
        let _ = h.flush();
    } else {
        let stdout = std::io::stdout();
        let mut h = stdout.lock();
        let _ = h.write_all(line.as_bytes());
        let _ = h.flush();
    }
}

pub const T_MAIN: &str = "xcp";
pub const T_OPS: &str = "libxcp::operations";
pub const T_PARFILE: &str = "libxcp::drivers::parfile";
pub const T_PARBLOCK: &str = "libxcp::drivers::parblock";
pub const T_FS: &str = "libfs::common";

#[macro_export]
macro_rules! error {
    ($target:expr, $($arg:tt)+) => {
        $crate::logger::log($crate::logger::Level::Error, $target, format_args!($($arg)+))
    };
}

#[macro_export]
macro_rules! warn {
    ($target:expr, $($arg:tt)+) => {
        $crate::logger::log($crate::logger::Level::Warn, $target, format_args!($($arg)+))
    };
}

#[macro_export]
macro_rules! info {
    ($target:expr, $($arg:tt)+) => {
        $crate::logger::log($crate::logger::Level::Info, $target, format_args!($($arg)+))
    };
}

#[macro_export]
macro_rules! debug {
    ($target:expr, $($arg:tt)+) => {
        if $crate::logger::enabled($crate::logger::Level::Debug) {
            $crate::logger::log($crate::logger::Level::Debug, $target, format_args!($($arg)+))
        }
    };
}
EOF
