#[derive(Debug)]
pub enum XcpError {
    InvalidArguments(String),
    InvalidSource(&'static str),
    InvalidDestination(&'static str),
    DestinationExists(&'static str, PathBuf),
    CopyError(String),
}

impl fmt::Display for XcpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            XcpError::InvalidArguments(s) => write!(f, "Invalid arguments: {}", s),
            XcpError::InvalidSource(s) => write!(f, "Invalid source: {}", s),
            XcpError::InvalidDestination(s) => write!(f, "Invalid destination: {}", s),
            XcpError::DestinationExists(s, p) => {
                write!(f, "Destination Exists: {}, {}", s, p.display())
            }
            XcpError::CopyError(s) => write!(f, "Error during copy: {}", s),
        }
    }
}

impl std::error::Error for XcpError {}

