{"command":"cd /workspace/src && cat > panics.rs <<'EOF'
//! Emulation of the standard panic report for a few well-defined failure
//! conditions, followed by an unwind of the current thread.

use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};

static FIRST_PANIC: AtomicBool = AtomicBool::new(true);

fn os_tid() -> i64 {
    unsafe { libc::syscall(libc::SYS_gettid) as i64 }
}

fn backtrace_enabled() -> bool {
    match std::env::var_os("RUST_BACKTRACE") {
        Some(v) => v != "0",
        None => false,
    }
}

pub fn report_panic(location: &str, msg: &str) -> ! {
    let t = std::thread::current();
    let name = t.name().unwrap_or("<unnamed>").to_string();
    let mut out = format!(
        "\nthread '{}' ({}) panicked at {}:\n{}\n",
        name,
        os_tid(),
        location,
        msg
    );
    if FIRST_PANIC.swap(false, Ordering::SeqCst) && !backtrace_enabled() {
        out.push_str(
            "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        );
    }
    {
        let stderr = std::io::stderr();
        let mut h = stderr.lock();
        let _ = h.write_all(out.as_bytes());
        let _ = h.flush();
    }
    std::panic::resume_unwind(Box::new(()));
}
EOF
