//! Parsing of human-readable byte sizes ("1MB", "16k", "2 GiB", ...).

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SizeError {
    Invalid,
    TooLarge,
}

impl fmt::Display for SizeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SizeError::Invalid => f.write_str("could not interpret string as byte size"),
            SizeError::TooLarge => f.write_str("byte size too large"),
        }
    }
}

impl std::error::Error for SizeError {}

const LOCATION: &str = "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/unbytify-0.2.0/src/lib.rs:101:14";

fn truncate_for_display(s: &str) -> (&str, &str) {
    const MAX: usize = 256;
    if s.len() <= MAX {
        return (s, "");
    }
    let mut end = MAX;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    (&s[..end], "[...]")
}

fn first_byte_slice(s: &str) -> &str {
    if s.is_empty() {
        crate::panics::report_panic(LOCATION, "byte index 1 is out of bounds of ``");
    }
    if !s.is_char_boundary(1) {
        let c = s.chars().next().unwrap();
        let (t, ellipsis) = truncate_for_display(s);
        let msg = format!(
            "byte index 1 is not a char boundary; it is inside {:?} (bytes 0..{}) of `{}`{}",
            c,
            c.len_utf8(),
            t,
            ellipsis
        );
        crate::panics::report_panic(LOCATION, &msg);
    }
    &s[..1]
}

const UNITS: [(char, u64); 7] = [
    ('k', 1 << 10),
    ('m', 1 << 20),
    ('g', 1 << 30),
    ('t', 1 << 40),
    ('p', 1 << 50),
    ('e', 1 << 60),
    ('b', 1),
];

pub fn unbytify(value: &str) -> Result<u64, SizeError> {
    let s = value.trim();
    if first_byte_slice(s) == "-" {
        return Err(SizeError::Invalid);
    }

    if let Ok(n) = s.parse::<f64>() {
        if n.fract() > 0.0 {
            return Err(SizeError::Invalid);
        }
        return Ok(n as u64);
    }

    let lower = s.to_lowercase();
    for (c, mult) in UNITS.iter() {
        let mut parts = lower.split(*c);
        let num = parts.next().unwrap_or("");
        if let Some(rest) = parts.next() {
            if rest.is_empty() || rest == "b" || rest == "ib" {
                if let Ok(n) = num.trim().parse::<f64>() {
                    return (n as u64).checked_mul(*mult).ok_or(SizeError::TooLarge);
                }
            }
        }
    }
    Err(SizeError::Invalid)
}
EOF"}

