//! Low-level filesystem helpers.

use std::ffi::{CString, OsStr, OsString};
use std::fs::{File, FileTimes};
use std::io;
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::os::unix::fs::MetadataExt;
use std::os::unix::io::AsRawFd;
use std::path::Path;

use crate::logger::T_FS;
use crate::{debug, warn};

const FICLONE: libc::c_ulong = 0x4004_9409;

/// Attempt to reflink the whole of `infd` into `outfd`.  Returns `true` on
/// success and `false` if the operation is not possible.
pub fn reflink(infd: &File, outfd: &File) -> bool {
    let r = unsafe { libc::ioctl(outfd.as_raw_fd(), FICLONE as _, infd.as_raw_fd()) };
    r == 0
