fn is_fallback_errno(e: &io::Error) -> bool {
    matches!(
        e.raw_os_error(),
        Some(libc::EXDEV) | Some(libc::ENOSYS) | Some(libc::EOPNOTSUPP)
    )
}

/// Copy up to `len` bytes using copy_file_range.  Offsets of `None` use the
/// current file positions.
fn cfr(
    infd: &File,
    off_in: Option<u64>,
    outfd: &File,
    off_out: Option<u64>,
    len: u64,
) -> io::Result<u64> {
    let mut oin: libc::loff_t = off_in.unwrap_or(0) as libc::loff_t;
    let mut oout: libc::loff_t = off_out.unwrap_or(0) as libc::loff_t;
    let pin: *mut libc::loff_t = if off_in.is_some() { &mut oin } else { std::ptr::null_mut() };
    let pout: *mut libc::loff_t = if off_out.is_some() { &mut oout } else { std::ptr::null_mut() };
    loop {
        let r = unsafe {
            libc::copy_file_range(
                infd.as_raw_fd(),
                pin,
                outfd.as_raw_fd(),
                pout,
                len as usize,
                0,
            )
        };
        if r < 0 {
            let e = io::Error::last_os_error();
            if e.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(e);
        }
        return Ok(r as u64);
    }
}

fn pread(fd: &File, buf: &mut [u8], off: u64) -> io::Result<usize> {
    use std::os::unix::fs::FileExt;
    loop {
        match fd.read_at(buf, off) {
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            r => return r,
        }
    }
}

fn pwrite_all(fd: &File, buf: &[u8], off: u64) -> io::Result<()> {
    use std::os::unix::fs::FileExt;
    fd.write_all_at(buf, off)
}

/// Userspace fallback copy of a range between explicit offsets.
fn uspace_copy(infd: &File, off_in: u64, outfd: &File, off_out: u64, len: u64) -> io::Result<u64> {
    let bufsize = std::cmp::min(len, 1024 * 1024) as usize;
    if bufsize == 0 {
        return Ok(0);
    }
    let mut buf = vec![0u8; bufsize];
    let n = pread(infd, &mut buf, off_in)?;
    if n == 0 {
        return Ok(0);
    }
    pwrite_all(outfd, &buf[..n], off_out)?;
    Ok(n as u64)
