    if r < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

pub fn list_xattr(fd: &File) -> io::Result<Vec<OsString>> {
    let raw = fd.as_raw_fd();
    loop {
        let size = unsafe { libc::flistxattr(raw, std::ptr::null_mut(), 0) };
        if size < 0 {
            return Err(io::Error::last_os_error());
        }
        if size == 0 {
            return Ok(vec![]);
        }
        let mut buf = vec![0u8; size as usize];
        let r = unsafe { libc::flistxattr(raw, buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
        if r < 0 {
            let e = io::Error::last_os_error();
            if e.raw_os_error() == Some(libc::ERANGE) {
                continue;
            }
            return Err(e);
        }
        buf.truncate(r as usize);
        return Ok(buf
            .split(|b| *b == 0)
            .filter(|s| !s.is_empty())
            .map(|s| OsString::from_vec(s.to_vec()))
            .collect());
    }
}

pub fn get_xattr(fd: &File, name: &OsStr) -> io::Result<Option<Vec<u8>>> {
    let raw = fd.as_raw_fd();
    let cname = CString::new(name.as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "nul in xattr name"))?;
    loop {
        let size = unsafe { libc::fgetxattr(raw, cname.as_ptr(), std::ptr::null_mut(), 0) };
        if size < 0 {
            let e = io::Error::last_os_error();
            if e.raw_os_error() == Some(libc::ENODATA) {
                return Ok(None);
            }
            return Err(e);
        }
        let mut buf = vec![0u8; size as usize];
        let r = unsafe {
            libc::fgetxattr(raw, cname.as_ptr(), buf.as_mut_ptr() as *mut libc::c_void, buf.len())
        };
        if r < 0 {
            let e = io::Error::last_os_error();
            if e.raw_os_error() == Some(libc::ERANGE) {
                continue;
            }
            if e.raw_os_error() == Some(libc::ENODATA) {
                return Ok(None);
            }
            return Err(e);
        }
        buf.truncate(r as usize);
        return Ok(Some(buf));
    }
}

pub fn set_xattr(fd: &File, name: &OsStr, value: &[u8]) -> io::Result<()> {
    let cname = CString::new(name.as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "nul in xattr name"))?;
    let r = unsafe {
        libc::fsetxattr(
            fd.as_raw_fd(),
            cname.as_ptr(),
            value.as_ptr() as *const libc::c_void,
            value.len(),
            0,
        )
    };
    if r < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

pub fn copy_xattr(infd: &File, outfd: &File) -> io::Result<()> {
    debug!(T_FS, "Starting xattr copy...");
    for attr in list_xattr(infd)? {
        if let Some(val) = get_xattr(infd, &attr)? {
            debug!(T_FS, "Copy xattr {:?}", attr);
            set_xattr(outfd, &attr, &val)?;
        }
    }
    Ok(())
}

pub fn copy_permissions(infd: &File, outfd: &File) -> io::Result<()> {
    if let Err(e) = copy_xattr(infd, outfd) {
        warn!(T_FS, "Failed to copy xattrs from {:?}: {}", infd, e);
    }
    let meta = infd.metadata()?;
    debug!(T_FS, "Performing permissions copy");
    outfd.set_permissions(meta.permissions())?;
    Ok(())
}

pub fn copy_timestamps(infd: &File, outfd: &File) -> io::Result<()> {
    let meta = infd.metadata()?;
    debug!(T_FS, "Performing timestamp copy");
    let times = FileTimes::new()
        .set_accessed(meta.accessed()?)
        .set_modified(meta.modified()?);
    outfd.set_times(times)?;
    Ok(())
}

pub fn copy_owner(infd: &File, outfd: &File) -> io::Result<()> {
    let meta = infd.metadata()?;
    std::os::unix::fs::fchown(outfd, Some(meta.uid()), Some(meta.gid()))
}

pub fn isatty(fd: libc::c_int) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

pub fn terminal_width(fd: libc::c_int) -> Option<u16> {
    let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
    let r = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) };
    if r == 0 && ws.ws_col > 0 {
        Some(ws.ws_col)
    } else {
        None
    }
}
EOF"}

