//! Numbered backups, following the naming scheme of `cp --backup=numbered`
//! (e.g. `file.txt.~3~`).

use std::ffi::OsString;
use std::io;
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

use crate::config::{Backup, Config};

fn parent_dir(path: &Path) -> PathBuf {
    match path.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
        _ => PathBuf::from("."),
    }
}

/// Find the highest existing backup number for `path`, if any.
fn highest_backup(path: &Path) -> io::Result<Option<u64>> {
    let fname = match path.file_name() {
        Some(f) => f.as_bytes().to_vec(),
        None => return Ok(None),
    };
    let mut prefix = fname.clone();
    prefix.extend_from_slice(b".~");

    let mut highest: Option<u64> = None;
    for entry in std::fs::read_dir(parent_dir(path))? {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let name = entry.file_name();
        let bytes = name.as_bytes();
        if bytes.len() <= prefix.len() + 1 || !bytes.starts_with(&prefix) || !bytes.ends_with(b"~") {
            continue;
        }
        let digits = &bytes[prefix.len()..bytes.len() - 1];
        if digits.is_empty() || !digits.iter().all(|b| b.is_ascii_digit()) {
            continue;
        }
        let s = match std::str::from_utf8(digits) {
            Ok(s) => s,
            Err(_) => continue,
        };
        if let Ok(n) = s.parse::<u64>() {
            highest = Some(match highest {
                Some(h) if h >= n => h,
                _ => n,
            });
        }
    }
    Ok(highest)
}

pub fn needs_backup(path: &Path, config: &Config) -> io::Result<bool> {
    Ok(match config.backup {
        Backup::None => false,
        Backup::Numbered => path.exists(),
        Backup::Auto => path.exists() && highest_backup(path)?.is_some(),
    })
}

pub fn next_backup_path(path: &Path) -> io::Result<PathBuf> {
    let next = match highest_backup(path)? {
        Some(n) => n.wrapping_add(1),
        None => 1,
    };
    let mut s: OsString = path.as_os_str().to_os_string();
    s.push(format!(".~{}~", next));
    Ok(PathBuf::from(s))
}
EOF"}

