//! Core copy operations shared by the drivers: tree walking, per-file copy
//! handles and status reporting.

use std::fs::{self, File, Metadata, OpenOptions};
use std::os::unix::fs::{FileTypeExt, MetadataExt};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::thread;

use anyhow::Result;
use crossbeam_channel::Sender;
use ignore::gitignore::Gitignore;
use walkdir::WalkDir;

use crate::backup;
use crate::config::{Config, Reflink};
use crate::errors::{MsgError, XcpError};
use crate::fsops;
use crate::logger::{T_MAIN, T_OPS};
use crate::{debug, error, info, warn};

#[derive(Debug)]
pub enum Operation {
    Copy(PathBuf, PathBuf),
    Link(PathBuf, PathBuf),
    Special(PathBuf, PathBuf),
}

#[derive(Debug)]
pub enum StatusUpdate {
    Copied(u64),
    Size(u64),
    Error(XcpError),
}

/// Sends status updates back to the main thread.
#[derive(Clone)]
pub struct Updater {
    tx: Sender<StatusUpdate>,
    batch_size: u64,
}

impl Updater {
    pub fn new(tx: Sender<StatusUpdate>, batch_size: u64) -> Self {
        Updater { tx, batch_size }
    }

    pub fn send(&self, update: StatusUpdate) -> Result<()> {
        if let StatusUpdate::Copied(_) = update {
            if self.batch_size == 0 {
                crate::panics::report_panic(
                    "libxcp/src/feedback.rs:98:16",
                    "attempt to divide by zero",
                );
            }
        }
        self.tx
            .send(update)
            .map_err(|_| anyhow::Error::new(MsgError("Error sending status update".to_string())))
    }
}

pub struct CopyHandle {
    pub infd: File,
    pub outfd: File,
    pub metadata: Metadata,
    pub config: Arc<Config>,
}

impl CopyHandle {
    pub fn new(from: &Path, to: &Path, config: &Arc<Config>) -> Result<CopyHandle> {
        let infd = File::open(from)?;
        let metadata = infd.metadata()?;
        let outfd = OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .open(to)?;
        let handle = CopyHandle {
            infd,
            outfd,
            metadata,
            config: config.clone(),
        };
        handle.outfd.set_len(handle.metadata.len())?;
        Ok(handle)
    }

    /// Attempt a reflink, depending on the configured mode.
    pub fn try_reflink(&self) -> Result<bool> {
        match self.config.reflink {
            Reflink::Never => Ok(false),
            Reflink::Auto | Reflink::Always => {
                debug!(
                    T_OPS,
                    "Attempting reflink from {:?}->{:?}", self.infd, self.outfd
                );
                if fsops::reflink(&self.infd, &self.outfd) {
                    debug!(T_OPS, "Reflink {:?} succeeded", self.outfd);
                    Ok(true)
                } else if self.config.reflink == Reflink::Always {
                    Err(anyhow::Error::new(MsgError(format!(
                        "Failed to reflink file and 'always' was specified: {:?}->{:?}",
                        self.infd, self.outfd
                    ))))
                } else {
                    debug!(T_OPS, "Failed to reflink, falling back to copy");
                    Ok(false)
                }
            }
        }
    }

    /// Copy the whole file in block-sized chunks (used by the per-file
    /// driver).
    pub fn copy_file(&self, updater: &Updater) -> Result<u64> {
        if self.try_reflink()? {
            return Ok(self.metadata.len());
        }
        let total = if fsops::probably_sparse(&self.infd)? {
            self.copy_sparse(updater)?
        } else {
            self.copy_bytes(0, self.metadata.len(), updater)?
        };
        Ok(total)
    }

    fn copy_bytes(&self, start: u64, end: u64, updater: &Updater) -> Result<u64> {
        let bsize = self.config.block_size;
        let mut copier = fsops::RangeCopier::new(&self.infd, &self.outfd);
        let mut pos = start;
        let mut total = 0u64;
        while pos < end {
            let len = std::cmp::min(bsize, end - pos);
            let n = copier.copy_at(pos, len)?;
            updater.send(StatusUpdate::Copied(n))?;
            if n == 0 {
                break;
            }
            pos += n;
            total += n;
        }
        Ok(total)
    }

    fn copy_sparse(&self, updater: &Updater) -> Result<u64> {
        let len = self.metadata.len();
        let mut pos = 0u64;
        let mut total = 0u64;
        while pos < len {
            match fsops::next_data_segment(&self.infd, pos)? {
                None => break,
                Some((data, hole)) => {
                    if data >= len {
                        break;
                    }
                    let end = std::cmp::min(hole, len);
                    total += self.copy_bytes(data, end, updater)?;
                    if hole <= pos {
                        break;
                    }
                    pos = hole;
                }
            }
        }
        Ok(total)
    }

    fn finalise_copy(&self) -> Result<()> {
        if !self.config.no_perms {
            fsops::copy_permissions(&self.infd, &self.outfd)?;
        }
        if !self.config.no_timestamps {
            fsops::copy_timestamps(&self.infd, &self.outfd)?;
        }
        if self.config.ownership && fsops::copy_owner(&self.infd, &self.outfd).is_err() {
            warn!(T_OPS, "Failed to copy file ownership: {:?}", self.infd);
        }
        if self.config.fsync {
            debug!(T_OPS, "Syncing file {:?}", self.outfd);
            self.outfd.sync_all()?;
        }
        Ok(())
    }
}

impl Drop for CopyHandle {
    fn drop(&mut self) {
        if let Err(e) = self.finalise_copy() {
            error!(
                T_OPS,
                "Error during finalising copy operation {:?} -> {:?}: {}", self.infd, self.outfd, e
            );
        }
    }
}

/// Perform any backup required before overwriting `to`.
pub fn backup_if_needed(to: &Path, config: &Config) -> Result<()> {
    if backup::needs_backup(to, config)? {
        let bpath = backup::next_backup_path(to)?;
        info!(T_OPS, "Backup: Rename {:?} to {:?}", to, bpath);
        fs::rename(to, &bpath)?;
    }
    Ok(())
}

/// Copy a single regular file, used by the per-file driver.
pub fn copy_single_file(from: &Path, to: &Path, config: &Arc<Config>, updater: &Updater) -> Result<u64> {
    backup_if_needed(to, config)?;
    let handle = CopyHandle::new(from, to, config)?;
    handle.copy_file(updater)
}

/// Recreate a special file (FIFO, socket, device) at the target.
pub fn copy_node(from: &Path, to: &Path) -> Result<()> {
    if to.exists() {
        fs::remove_file(to)?;
    }
    let meta = fs::symlink_metadata(from)?;
    fsops::mknod(to, meta.mode(), meta.rdev())?;
    Ok(())
}

pub fn make_symlink(from: &Path, to: &Path) {
    let _ = std::os::unix::fs::symlink(from, to);
}

fn ignore_filter(entry: &walkdir::DirEntry, gitignore: &Option<Gitignore>) -> bool {
    match gitignore {
        None => true,
        Some(gi) => !gi
            .matched(entry.path(), entry.file_type().is_dir())
            .is_ignore(),
    }
}

/// Walk the source trees and dispatch operations to the copy workers.
pub fn tree_walker(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
    work_tx: Sender<Operation>,
    updater: Updater,
) -> Result<()> {
    debug!(T_OPS, "Starting walk worker {:?}", thread::current().id());

    for source in sources {
        let sourcedir = match source.components().last() {
            Some(c) => c,
            None => {
                return Err(XcpError::InvalidSource("Failed to find source directory name.").into())
            }
        };

        let target_base = if dest.exists() && dest.is_dir() && !config.no_target_directory {
            dest.join(sourcedir)
        } else {
            dest.clone()
        };
        debug!(T_OPS, "Target base is {:?}", target_base);

        let gitignore = if config.gitignore {
            let gipath = source.join(".gitignore");
            info!(T_OPS, "Using .gitignore file {:?}", gipath);
            let (gi, _err) = Gitignore::new(&gipath);
            Some(gi)
        } else {
            None
        };

        for entry in WalkDir::new(&source)
            .into_iter()
            .filter_entry(|e| ignore_filter(e, &gitignore))
        {
            debug!(T_OPS, "Got tree entry {:?}", entry);
            let entry = entry?;
            let epath = entry.path();

            let (from, meta) = if config.dereference {
                let cpath = epath.canonicalize()?;
                debug!(T_OPS, "Dereferencing {:?} into {:?}", epath, cpath);
                let meta = cpath.metadata()?;
                (cpath, meta)
            } else {
                let meta = entry.metadata()?;
                (epath.to_path_buf(), meta)
            };

            let rel = epath.strip_prefix(&source)?;
            let target = if rel.as_os_str().is_empty() {
                target_base.clone()
            } else {
                target_base.join(rel)
            };

            if config.no_clobber && target.exists() {
                updater.send(StatusUpdate::Error(XcpError::DestinationExists(
                    "Destination file exists and --no-clobber is set.",
                    target,
                )))?;
                return Ok(());
            }

            let ft = meta.file_type();
            if ft.is_dir() {
                debug!(T_OPS, "Creating target directory {:?}", target);
                if let Err(err) = fs::create_dir_all(&target) {
                    let msg = format!("Error creating target directory: {}", err);
                    error!(T_OPS, "{}", msg);
                    return Err(XcpError::CopyError(msg).into());
                }
                if config.ownership {
                    if let Err(e) =
                        std::os::unix::fs::chown(&target, Some(meta.uid()), Some(meta.gid()))
                    {
                        warn!(T_OPS, "Failed to copy directory ownership: {:?}: {}", target, e);
                    }
                }
            } else if ft.is_symlink() {
                let lfile = fs::read_link(&from)?;
                debug!(T_OPS, "Send symlink operation {:?} to {:?}", lfile, target);
                work_tx
                    .send(Operation::Link(lfile, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            } else if ft.is_file() {
                debug!(T_OPS, "Send copy operation {:?} to {:?}", from, target);
                updater.send(StatusUpdate::Size(meta.len()))?;
                work_tx
                    .send(Operation::Copy(from, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            } else {
                let _ = ft.is_fifo();
                debug!(T_OPS, "Special file found: {:?} to {:?}", from, target);
                work_tx
                    .send(Operation::Special(from, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            }
        }
    }

    debug!(T_OPS, "Walk-worker finished: {:?}", thread::current().id());
    let _ = T_MAIN;
    Ok(())
}
EOF"}

