        info!(T_OPS, "Backup: Rename {:?} to {:?}", to, bpath);
        fs::rename(to, &bpath)?;
    }
    Ok(())
}

/// Copy a single regular file, used by the per-file driver.
pub fn copy_single_file(from: &Path, to: &Path, config: &Arc<Config>, updater: &Updater) -> Result<u64> {
    backup_if_needed(to, config)?;
    let handle = CopyHandle::new(from, to, config)?;
    handle.copy_file(updater)
}

/// Recreate a special file (FIFO, socket, device) at the target.
pub fn copy_node(from: &Path, to: &Path) -> Result<()> {
    if to.exists() {
        fs::remove_file(to)?;
    }
    let meta = fs::symlink_metadata(from)?;
    fsops::mknod(to, meta.mode(), meta.rdev())?;
    Ok(())
}

pub fn make_symlink(from: &Path, to: &Path) {
    let _ = std::os::unix::fs::symlink(from, to);
}

fn ignore_filter(entry: &walkdir::DirEntry, gitignore: &Option<Gitignore>) -> bool {
    match gitignore {
        None => true,
        Some(gi) => !gi
            .matched(entry.path(), entry.file_type().is_dir())
            .is_ignore(),
    }
}

/// Walk the source trees and dispatch operations to the copy workers.
pub fn tree_walker(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
    work_tx: Sender<Operation>,
    updater: Updater,
) -> Result<()> {
    debug!(T_OPS, "Starting walk worker {:?}", thread::current().id());

    for source in sources {
        let sourcedir = match source.components().last() {
            Some(c) => c,
            None => {
                return Err(XcpError::InvalidSource("Failed to find source directory name.").into())
            }
        };

        let target_base = if dest.exists() && dest.is_dir() && !config.no_target_directory {
            dest.join(sourcedir)
        } else {
            dest.clone()
        };
        debug!(T_OPS, "Target base is {:?}", target_base);

        let gitignore = if config.gitignore {
            let gipath = source.join(".gitignore");
            info!(T_OPS, "Using .gitignore file {:?}", gipath);
            let (gi, _err) = Gitignore::new(&gipath);
            Some(gi)
        } else {
            None
        };

        for entry in WalkDir::new(&source)
            .into_iter()
            .filter_entry(|e| ignore_filter(e, &gitignore))
        {
            debug!(T_OPS, "Got tree entry {:?}", entry);
            let entry = entry?;
            let epath = entry.path();

            let (from, meta) = if config.dereference {
                let cpath = epath.canonicalize()?;
                debug!(T_OPS, "Dereferencing {:?} into {:?}", epath, cpath);
                let meta = cpath.metadata()?;
                (cpath, meta)
            } else {
                let meta = entry.metadata()?;
                (epath.to_path_buf(), meta)
            };

            let rel = epath.strip_prefix(&source)?;
            let target = if rel.as_os_str().is_empty() {
                target_base.clone()
            } else {
                target_base.join(rel)
            };

            if config.no_clobber && target.exists() {
                updater.send(StatusUpdate::Error(XcpError::DestinationExists(
                    "Destination file exists and --no-clobber is set.",
                    target,
                )))?;
                return Ok(());
            }

            let ft = meta.file_type();
            if ft.is_dir() {
                debug!(T_OPS, "Creating target directory {:?}", target);
                if let Err(err) = fs::create_dir_all(&target) {
                    let msg = format!("Error creating target directory: {}", err);
                    error!(T_OPS, "{}", msg);
                    return Err(XcpError::CopyError(msg).into());
                }
                if config.ownership {
                    if let Err(e) =
                        std::os::unix::fs::chown(&target, Some(meta.uid()), Some(meta.gid()))
                    {
                        warn!(T_OPS, "Failed to copy directory ownership: {:?}: {}", target, e);
                    }
                }
            } else if ft.is_symlink() {
                let lfile = fs::read_link(&from)?;
                debug!(T_OPS, "Send symlink operation {:?} to {:?}", lfile, target);
                work_tx
                    .send(Operation::Link(lfile, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            } else if ft.is_file() {
                debug!(T_OPS, "Send copy operation {:?} to {:?}", from, target);
                updater.send(StatusUpdate::Size(meta.len()))?;
                work_tx
                    .send(Operation::Copy(from, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            } else {
                let _ = ft.is_fifo();
                debug!(T_OPS, "Special file found: {:?} to {:?}", from, target);
                work_tx
                    .send(Operation::Special(from, target))
                    .map_err(|_| XcpError::CopyError("Error sending operation".to_string()))?;
            }
        }
    }

    debug!(T_OPS, "Walk-worker finished: {:?}", thread::current().id());
    let _ = T_MAIN;
    Ok(())
}
