//! A simple terminal progress bar, drawn on stderr when it is a terminal.

use std::io::Write;
use std::time::{Duration, Instant};

use crate::fsops;

pub struct ProgressBar {
    enabled: bool,
    colour: bool,
    pos: u64,
    len: u64,
    start: Instant,
    last_draw: Option<Instant>,
    drawn_lines: usize,
}

fn env_is(name: &str, default: &str, not: &str) -> bool {
    std::env::var(name).unwrap_or_else(|_| default.to_string()) != not
}

fn colours_enabled() -> bool {
    let supported = fsops::isatty(2)
        && std::env::var("NO_COLOR").is_err()
        && match std::env::var("TERM") {
            Ok(t) => t != "dumb",
            Err(_) => false,
        };
    (supported && env_is("CLICOLOR", "1", "0")) || env_is("CLICOLOR_FORCE", "0", "0")
}

pub fn binary_bytes(n: u64) -> String {
    if n < 1024 {
        return format!("{} B", n);
    }
    const UNITS: [&str; 8] = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];
    let mut v = n as f64 / 1024.0;
    let mut i = 0;
    while v >= 1024.0 && i < UNITS.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.2} {}", v, UNITS[i])
}

fn centre(s: &str, width: usize) -> String {
    let len = s.chars().count();
    if len >= width {
        return s.to_string();
    }
    let total = width - len;
    let left = total / 2;
    let right = total - left;
    format!("{}{}{}", " ".repeat(left), s, " ".repeat(right))
}

fn hms(secs: u64) -> String {
    format!("{:02}:{:02}:{:02}", secs / 3600, (secs % 3600) / 60, secs % 60)
}

impl ProgressBar {
    pub fn new(enabled: bool) -> ProgressBar {
        let enabled = enabled && fsops::isatty(2);
        ProgressBar {
            enabled,
            colour: enabled && colours_enabled(),
            pos: 0,
            len: 0,
            start: Instant::now(),
            last_draw: None,
            drawn_lines: 0,
        }
    }

    pub fn inc(&mut self, n: u64) {
        if !self.enabled {
            return;
        }
        self.pos = self.pos.saturating_add(n);
        self.draw(false);
    }

    pub fn inc_length(&mut self, n: u64) {
        if !self.enabled {
            return;
        }
        self.len = self.len.saturating_add(n);
        self.draw(false);
    }

    pub fn finish(&mut self) {
        if !self.enabled {
            return;
        }
        self.pos = self.len;
        self.draw(true);
        let _ = std::io::stderr().write_all(b"\n");
        self.drawn_lines = 0;
    }

    fn render(&self) -> Vec<String> {
        let width = fsops::terminal_width(2).unwrap_or(80) as usize;
        let barw = width.saturating_sub(2);
        let fract = if self.len == 0 {
            1.0f64
        } else {
            (self.pos as f64 / self.len as f64).clamp(0.0, 1.0)
        };
        let fill = fract * barw as f64;
        let whole = fill as usize;
        let head = if fill > 0.0 && whole < barw { 1 } else { 0 };
        let rest = barw.saturating_sub(whole).saturating_sub(head);
        let mut filled = "#".repeat(whole);
        if head == 1 {
            filled.push('>');
        }
        let empty = "-".repeat(rest);
        let bar = if self.colour {
            let mut s = String::new();
            if !filled.is_empty() {
                s.push_str(&format!("\x1b[36m{}\x1b[0m", filled));
            }
            if !empty.is_empty() {
                s.push_str(&format!("\x1b[34m{}\x1b[0m", empty));
            }
            s
        } else {
            format!("{}{}", filled, empty)
        };
        let line1 = format!("[{}]", bar);

        let elapsed = self.start.elapsed().as_secs_f64();
        let rate = if elapsed > 0.0 { self.pos as f64 / elapsed } else { 0.0 };
        let eta = if rate > 0.0 && self.len > self.pos {
            ((self.len - self.pos) as f64 / rate) as u64
        } else {
            0
        };
        let percent = (fract * 100.0) as u64;
        let speed = format!("{}/s", binary_bytes(rate as u64));
        let line2 = format!(
            "{:>11} / {:<11} | {:>3}% | {} | {} remaining",
            binary_bytes(self.pos),
            binary_bytes(self.len),
            percent,
            centre(&speed, 13),
            hms(eta)
        );
        vec![line1, line2]
    }

    fn draw(&mut self, force: bool) {
        let now = Instant::now();
        if !force {
            if let Some(last) = self.last_draw {
                if now.duration_since(last) < Duration::from_millis(50) {
                    return;
                }
            }
        }
        self.last_draw = Some(now);
        let lines = self.render();
        let mut out = String::new();
        if self.drawn_lines > 0 {
            out.push('\r');
            if self.drawn_lines > 1 {
                out.push_str(&format!("\x1b[{}A", self.drawn_lines - 1));
            }
        }
        for (i, l) in lines.iter().enumerate() {
            out.push_str("\x1b[2K");
            out.push_str(l);
            if i + 1 < lines.len() {
                out.push('\n');
            }
        }
        self.drawn_lines = lines.len();
        let stderr = std::io::stderr();
        let mut h = stderr.lock();
        let _ = h.write_all(out.as_bytes());
        let _ = h.flush();
    }
}
