                .help("Copy into a subdirectory of the target"),
        )
        .arg(
            Arg::new("fsync")
                .long("fsync")
                .action(ArgAction::SetTrue)
                .help("Sync each file to disk after writing"),
        )
        .arg(
            Arg::new("reflink")
                .long("reflink")
                .value_name("REFLINK")
                .action(ArgAction::Set)
                .default_value("auto")
                .value_parser(|s: &str| s.parse::<Reflink>())
                .help("Reflink options")
                .long_help(
                    "Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting.",
                ),
        )
        .arg(
            Arg::new("backup")
                .long("backup")
                .value_name("BACKUP")
                .action(ArgAction::Set)
                .default_value("none")
                .value_parser(|s: &str| s.parse::<Backup>())
