fn parse_opts() -> Opts {
    let m = build_cli().get_matches();
    Opts {
        verbose: m.get_count("verbose"),
        recursive: m.get_flag("recursive"),
        dereference: m.get_flag("dereference"),
        workers: *m.get_one::<usize>("workers").unwrap(),
        block_size: *m.get_one::<u64>("block_size").unwrap(),
        no_clobber: m.get_flag("no_clobber"),
        force: m.get_flag("force"),
        gitignore: m.get_flag("gitignore"),
        glob: m.get_flag("glob"),
        no_progress: m.get_flag("no_progress"),
        no_perms: m.get_flag("no_perms"),
        no_timestamps: m.get_flag("no_timestamps"),
        ownership: m.get_flag("ownership"),
        driver: *m.get_one::<Driver>("driver").unwrap(),
        no_target_directory: m.get_flag("no_target_directory"),
        target_directory: m.get_one::<PathBuf>("target_directory").cloned(),
        fsync: m.get_flag("fsync"),
        reflink: *m.get_one::<Reflink>("reflink").unwrap(),
        backup: *m.get_one::<Backup>("backup").unwrap(),
        paths: m
            .get_many::<PathBuf>("paths")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    }
}

fn expand_sources(sources: &[PathBuf], opts: &Opts) -> Result<Vec<PathBuf>> {
    if opts.glob {
        let mut expanded = Vec::new();
        for s in sources {
            let pattern = s.to_string_lossy();
            for entry in glob::glob(&pattern)? {
                if let Ok(p) = entry {
                    expanded.push(p);
                }
            }
        }
        Ok(expanded)
    } else {
        Ok(sources.to_vec())
    }
}

fn num_workers(requested: usize) -> usize {
    if requested == 0 {
        thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    } else {
        requested
    }
}

fn main() -> Result<()> {
    let opts = parse_opts();
    logger::init(opts.verbose);

    if opts.reflink == Reflink::Never {
        warn!(
            T_MAIN,
            "--reflink=never is selected, however the Linux kernel may override this."
        );
    }

    if opts.no_clobber && opts.force {
        return Err(XcpError::InvalidArguments(
            "--force and --noclobber cannot be set at the same time.".to_string(),
        )
        .into());
    }

    let (sources, dest) = if let Some(td) = &opts.target_directory {
        (opts.paths.clone(), td.clone())
    } else {
        if opts.paths.is_empty() {
            return Err(XcpError::InvalidArguments("Insufficient arguments".to_string()).into());
        }
        let n = opts.paths.len();
        (opts.paths[..n - 1].to_vec(), opts.paths[n - 1].clone())
    };

    let sources = expand_sources(&sources, &opts)?;
    if sources.is_empty() {
        return Err(XcpError::InvalidSource("No source files found.").into());
    }

    if sources.len() > 1 && !dest.is_dir() {
        return Err(XcpError::InvalidDestination(
            "Multiple sources and destination is not a directory.",
        )
        .into());
    }

    if sources.len() == 1 && sources[0].is_dir() && dest.exists() && !dest.is_dir() {
        return Err(XcpError::InvalidDestination("Cannot copy a directory to a file.").into());
    }

    for source in &sources {
        info!(T_MAIN, "Copying source {:?} to {:?}", source, dest);
        if !source.exists() {
            return Err(XcpError::InvalidSource("Source does not exist.").into());
        }
        if source.is_dir() && !opts.recursive {
            return Err(XcpError::InvalidSource(
                "Source is directory and --recursive not specified.",
            )
            .into());
        }
        if source == &dest {
            return Err(XcpError::InvalidSource("Cannot copy a directory into itself").into());
        }
    }

    let config = Arc::new(Config {
        workers: num_workers(opts.workers),
        block_size: opts.block_size,
        gitignore: opts.gitignore,
        no_clobber: opts.no_clobber,
        no_perms: opts.no_perms,
        no_timestamps: opts.no_timestamps,
        ownership: opts.ownership,
        dereference: opts.dereference,
        no_target_directory: opts.no_target_directory,
        fsync: opts.fsync,
        reflink: opts.reflink,
        backup: opts.backup,
    });

    let (stat_tx, stat_rx) = cbc::unbounded::<StatusUpdate>();
    let updater = Updater::new(stat_tx, config.block_size);
    let driver = opts.driver;

    let handle = {
        let config = config.clone();
        thread::spawn(move || match driver {
            Driver::ParFile => drivers::parfile::copy_all(sources, dest, config, updater),
            Driver::ParBlock => drivers::parblock::copy_all(sources, dest, config, updater),
        })
    };

    let mut pb = progress::ProgressBar::new(!opts.no_progress);
    for update in stat_rx.iter() {
        match update {
            StatusUpdate::Copied(n) => pb.inc(n),
            StatusUpdate::Size(n) => pb.inc_length(n),
            StatusUpdate::Error(e) => {
                error!(T_MAIN, "Received error: {}", e);
                return Err(e.into());
            }
        }
    }

    handle
        .join()
        .map_err(|_| XcpError::CopyError("Error during copy operation".to_string()))??;

    pb.finish();
    info!(T_MAIN, "Copy complete");

    Ok(())
}
