fn build_cli() -> Command {
    Command::new("xcp")
        .version("0.24.3")
        .about("A (partial) clone of the Unix `cp` command with progress and pluggable drivers.")
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Verbosity")
                .long_help("Verbosity.\n\nCan be specified multiple times to increase logging."),
        )
        .arg(
            Arg::new("recursive")
                .short('r')
                .long("recursive")
                .action(ArgAction::SetTrue)
                .help("Copy directories recursively"),
        )
        .arg(
            Arg::new("dereference")
                .short('L')
                .long("dereference")
                .action(ArgAction::SetTrue)
                .help("Dereference symlinks in source")
                .long_help(
                    "Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files.",
                ),
        )
        .arg(
            Arg::new("workers")
                .short('w')
                .long("workers")
                .value_name("WORKERS")
                .action(ArgAction::Set)
                .default_value("4")
                .value_parser(|s: &str| s.parse::<usize>())
                .help("Number of parallel workers")
                .long_help(
                    "Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs.",
                ),
        )
        .arg(
            Arg::new("block_size")
                .long("block-size")
                .value_name("BLOCK_SIZE")
                .action(ArgAction::Set)
                .default_value("1MB")
                .value_parser(|s: &str| unbytify::unbytify(s))
                .help("Block size for operations")
                .long_help(
                    "Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver.",
                ),
        )
        .arg(
            Arg::new("no_clobber")
                .short('n')
                .long("no-clobber")
                .action(ArgAction::SetTrue)
                .help("Do not overwrite an existing file"),
        )
        .arg(
            Arg::new("force")
                .short('f')
                .long("force")
                .action(ArgAction::SetTrue)
                .help("Force (compatability only)")
                .long_help(
                    "Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error.",
                ),
        )
        .arg(
            Arg::new("gitignore")
                .long("gitignore")
                .action(ArgAction::SetTrue)
                .help("Use .gitignore if present")
                .long_help(
                    "Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped.",
                ),
        )
        .arg(
            Arg::new("glob")
                .short('g')
                .long("glob")
                .action(ArgAction::SetTrue)
                .help("Expand file patterns")
                .long_help(
                    "Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)",
                ),
        )
        .arg(
            Arg::new("no_progress")
                .long("no-progress")
                .action(ArgAction::SetTrue)
                .help("Disable progress bar"),
        )
        .arg(
            Arg::new("no_perms")
                .long("no-perms")
                .action(ArgAction::SetTrue)
                .help("Do not copy the file permissions"),
        )
        .arg(
            Arg::new("no_timestamps")
                .long("no-timestamps")
                .action(ArgAction::SetTrue)
                .help("Do not copy the file timestamps"),
        )
        .arg(
            Arg::new("ownership")
                .short('o')
                .long("ownership")
                .action(ArgAction::SetTrue)
                .help("Copy ownership")
                .long_help(
                    "Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues.",
                ),
        )
        .arg(
            Arg::new("driver")
                .long("driver")
                .value_name("DRIVER")
                .action(ArgAction::Set)
                .default_value("parfile")
                .value_parser(|s: &str| s.parse::<Driver>())
                .help("Driver to use, defaults to 'file-parallel'")
                .long_help(
                    "Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'.",
                ),
        )
        .arg(
            Arg::new("no_target_directory")
                .short('T')
                .long("no-target-directory")
                .action(ArgAction::SetTrue)
                .help("Target should not be a directory")
                .long_help(
                    "Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target.",
                ),
        )
        .arg(
            Arg::new("target_directory")
                .long("target-directory")
                .value_name("TARGET_DIRECTORY")
                .action(ArgAction::Set)
                .value_parser(clap::value_parser!(PathBuf))
                .help("Copy into a subdirectory of the target"),
        )
        .arg(
            Arg::new("fsync")
                .long("fsync")
                .action(ArgAction::SetTrue)
                .help("Sync each file to disk after writing"),
        )
        .arg(
            Arg::new("reflink")
                .long("reflink")
                .value_name("REFLINK")
