        for name in sorted(dns + fns):
            p = os.path.join(dp, name)
            rel = os.path.relpath(p, root)
            st = os.lstat(p)
            mode = stat.S_IMODE(st.st_mode)
            if stat.S_ISLNK(st.st_mode):
                out.append(f"{rel} L {os.readlink(p)}")
            elif stat.S_ISDIR(st.st_mode):
                out.append(f"{rel} D {mode:o}")
            elif stat.S_ISREG(st.st_mode):
                try:
                    h = hashlib.md5(open(p,'rb').read()).hexdigest()[:10]
                except Exception as e:
                    h = "UNREADABLE"
                extra = f" m={st.st_mtime_ns}" if mtimes else ""
                out.append(f"{rel} F {mode:o} {st.st_size} {h} blk={st.st_blocks}{extra}")
