            else:
                out.append(f"{rel} ? {mode:o}")
    return out

TS = re.compile(r'\b\d\d:\d\d:\d\d \[')
def norm(s, d):
    s = s.replace(d, "<DIR>")
    s = TS.sub('TT:TT:TT [', s)
    s = re.sub(r"\((\d+)\) panicked", "(N) panicked", s)
    return s

def run_one(binary, name, setup, cmd, sort_out, env):
    d = os.path.join(BASE, name)
    if os.path.exists(d):
        subprocess.run(["chmod", "-R", "u+rwx", d])
        shutil.rmtree(d)
    os.makedirs(d)
    subprocess.run(["bash", "-c", setup], cwd=d, check=True)
    full = cmd.replace("XCP", binary)
    e = dict(os.environ); e.update(env)
    p = subprocess.run(["bash", "-c", full], cwd=d, capture_output=True, env=e, timeout=60)
    o = norm(p.stdout.decode('utf8','replace'), d)
    er = norm(p.stderr.decode('utf8','replace'), d)
    if sort_out:
        o = "\n".join(sorted(o.splitlines()))
        er = "\n".join(sorted(er.splitlines()))
    subprocess.run(["chmod", "-R", "u+rwx", d])
    snap = snapshot(d)
    return p.returncode, o, er, snap

def compare(name, setup, cmd, sort_out=False, env={}, quiet=False):
    a = run_one(ORIG, name + "_A", setup, cmd, sort_out, env)
    b = run_one(MINE, name + "_B", setup, cmd, sort_out, env)
    ok = True
    labels = ["rc", "stdout", "stderr", "tree"]
    msgs = []
    for i in range(4):
        if a[i] != b[i]:
            ok = False
            if i == 3:
                sa, sb = set(a[3]), set(b[3])
                msgs.append(f"  tree diff:\n    orig only: {sorted(sa-sb)}\n    mine only: {sorted(sb-sa)}")
            else:
                msgs.append(f"  {labels[i]} differs:\n--- orig\n{a[i]}\n--- mine\n{b[i]}")
    print(("OK   " if ok else "FAIL ") + name + ": " + cmd)
    if not ok:
        for m in msgs: print(m)
    return ok

if __name__ == "__main__":
    pass
