            pos: 0,
            len: 0,
            start: Instant::now(),
            last_draw: None,
            drawn_rows: 0,
            finished: false,
        }
    }

    pub fn inc(&mut self, n: u64) {
        if !self.enabled {
            return;
        }
        self.pos = self.pos.saturating_add(n);
        self.draw(false);
    }

    pub fn inc_length(&mut self, n: u64) {
        if !self.enabled {
            return;
        }
        self.len = self.len.saturating_add(n);
        self.draw(false);
    }

    pub fn finish(&mut self) {
        if !self.enabled || self.finished {
            return;
        }
        self.pos = self.len;
        self.finished = true;
        self.draw(true);
    }

    fn render(&self, width: usize) -> Vec<String> {
        let barw = width.saturating_sub(2);
        let fract = if self.len == 0 {
            1.0f64
        } else {
            (self.pos as f64 / self.len as f64).clamp(0.0, 1.0)
        };
        let fill = fract * barw as f64;
        let whole = fill as usize;
        let head = fill > 0.0 && whole < barw;
        let rest = barw.saturating_sub(whole).saturating_sub(head as usize);
        let mut filled = "#".repeat(whole);
        if head {
            filled.push('>');
        }
