            "{:>11} / {:<11} | {:>3}% | {} | {} remaining",
            binary_bytes(self.pos as f64),
            binary_bytes(self.len as f64),
            percent,
            centre(&speed, 13),
            hms(eta)
        );
        vec![line1, line2]
    }

    fn draw(&mut self, force: bool) {
        let now = Instant::now();
        if !force {
            if let Some(last) = self.last_draw {
                if now.duration_since(last) < Duration::from_millis(50) {
                    return;
                }
            }
