        let mut h = stderr.lock();
        let _ = h.write_all(out.as_bytes());
        let _ = h.flush();
    }
}

impl Drop for ProgressBar {
    fn drop(&mut self) {
        if self.enabled && !self.finished && self.drawn_rows > 0 {
            let out = clear_rows(self.drawn_rows);
            let stderr = std::io::stderr();
            let mut h = stderr.lock();
